example_item.example_item_data:
% Open the view on the fifth beat of a simulated record and step to the next.
recording = ecglab.simulate('Seconds', 30, 'Ectopic', 0.1, 'Seed', 1);
handle = ecglab.beat(recording, 'Beat', 5, 'Interactive', false);
ecglab.beat(handle, 'next');

% Reuse a whole analysis so the beat is not recomputed, and save the page.
recording = ecglab.simulate('Seconds', 30, 'Seed', 2);
analysis = ecglab.analyze(recording);
ecglab.beat(analysis, 'Beat', 3, 'OutputImage', [tempdir(), '/beat.png']);
